#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static uint64_t rank_hand(const char *h) {
    int count[15] = {0}, ranks[5], freq[5], groups = 0;
    char suits[5];
    for (int i = 0; i < 5; i++) {
        while (*h == ' ')
            h++;
        if (!*h)
            return UINT64_MAX;
        int r;
        if (*h == '1' && h[1] == '0') {
            r = 10;
            h += 2;
        } else {
            const char *p = strchr("23456789TJQKA", *h++);
            if (!p)
                return UINT64_MAX;
            r = (int)(p - "23456789TJQKA") + 2;
        }
        if (!*h || !strchr("CDHS", *h))
            return UINT64_MAX;
        count[r]++;
        suits[i] = *h++;
        if (*h && !isspace((unsigned char)*h))
            return UINT64_MAX;
    }
    while (isspace((unsigned char)*h))
        h++;
    if (*h)
        return UINT64_MAX;
    for (int r = 14; r >= 2; r--)
        if (count[r]) {
            ranks[groups] = r;
            freq[groups++] = count[r];
        }
    for (int i = 0; i < groups; i++)
        for (int j = i + 1; j < groups; j++)
            if (freq[j] > freq[i]) {
                int t = freq[i];
                freq[i] = freq[j];
                freq[j] = t;
                t = ranks[i];
                ranks[i] = ranks[j];
                ranks[j] = t;
            }
    bool flush = true;
    for (int i = 1; i < 5; i++)
        if (suits[i] != suits[0])
            flush = false;
    if (groups == 5 && ranks[0] == 14 && ranks[1] == 5) {
        ranks[0] = 5;
        ranks[1] = 4;
        ranks[2] = 3;
        ranks[3] = 2;
        ranks[4] = 1;
    }
    bool straight = groups == 5 && ranks[0] - ranks[4] == 4;
    int category = freq[0] == 5                   ? 9
                   : straight && flush            ? 8
                   : freq[0] == 4                 ? 7
                   : freq[0] == 3 && freq[1] == 2 ? 6
                   : flush                        ? 5
                   : straight                     ? 4
                   : freq[0] == 3                 ? 3
                   : freq[0] == 2 && freq[1] == 2 ? 2
                   : freq[0] == 2                 ? 1
                                                  : 0;
    uint64_t value = (uint64_t)category;
    for (int i = 0; i < 5; i++)
        value = value * 15 + (i < groups ? (unsigned)ranks[i] : 0);
    return value;
}
size_t best_hands(const char *const *h, size_t n, size_t *out) {
    uint64_t best = 0;
    size_t k = 0;
    for (size_t i = 0; i < n; i++) {
        uint64_t r = rank_hand(h[i]);
        if (r == UINT64_MAX)
            return 0;
        if (!k || r > best) {
            best = r;
            k = 0;
            out[k++] = i;
        } else if (r == best)
            out[k++] = i;
    }
    return k;
}

