#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    size_t o[10];
    const char *a[] = {"4S 5H 5S 5D 5C", "7S 8S 9S 6S 10S"};
    assert(best_hands(a, 2, o) == 1 && o[0] == 1);
    const char *b[] = {"4D AD 3D 2D 5D", "2H 3H 4H 5H 6H"};
    assert(best_hands(b, 2, o) == 1 && o[0] == 1);
    const char *c[] = {"2S 3S 4S 5S 6S", "2H 3H 4H 5H 6H"};
    assert(best_hands(c, 2, o) == 2);
    const char *d[] = {"5H 5S 5D 9S 9D", "5H 5S 5D 8S 8D"};
    assert(best_hands(d, 2, o) == 1 && o[0] == 0);
    assert(best_hands(NULL, 0, o) == 0);
    const char *five[] = {"AC AC AC AC AC", "10H JH QH KH AH"};
    assert(best_hands(five, 2, o) == 1 && o[0] == 0);
    const char *bad[] = {"2Z 3H 4H 5H 6H"};
    assert(best_hands(bad, 1, o) == 0);
    const char *short_hand[] = {"AC"};
    assert(best_hands(short_hand, 1, o) == 0);
    {
        const char *values[] = {"4S 5S 7H 8D JC"};
        size_t actual[100];
        assert(best_hands(values, 1, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"4D 5S 6S 8D 3C", "2S 4C 7S 9H 10H", "3S 4S 5D 6H JH"};
        size_t actual[100];
        assert(best_hands(values, 3, actual) == 1);
        assert(actual[0] == 2);
    }
    {
        const char *values[] = {"4D 5S 6S 8D 3C", "2S 4C 7S 9H 10H", "3S 4S 5D 6H JH",
                                "3H 4H 5C 6C JD"};
        size_t actual[100];
        assert(best_hands(values, 4, actual) == 2);
        assert(actual[0] == 2);
        assert(actual[1] == 3);
    }
    {
        const char *values[] = {"3S 5H 6S 8D 7H", "2S 5D 6D 8C 7S"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"2S 5H 6S 8D 7H", "3S 4D 6D 8C 7S"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"4S 5H 6C 8D KH", "2S 4H 6S 4D JH"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"4S 2H 6S 2D JH", "2S 4H 6C 4D JD"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"4H 4S AH JC 3D", "4C 4D AS 5D 6C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"2S 8H 6S 8D JH", "4S 5H 4C 8C 5C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2S 8H 2D 8D 3H", "4S 5H 4C 8S 5D"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"2S QS 2C QD JH", "JD QH JS 8D QC"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"JD QH JS 8D QC", "JS QS JC 2D QD"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"6S 6H 3S 3H AS", "7H 7S 2H 2S AC"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"5C 2S 5S 4H 4C", "6S 2S 6H 7C 2C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2S 8H 2H 8D JH", "4S 5H 4C 8S 4H"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2S 2H 2C 8D JH", "4S AH AS 8C AD"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
