        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2C 3D 7H 5H 2S", "QS KH AC 2D 3S"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"4S 6C 7S 8D 5H", "5S 7H 8S 9D 6H"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2H 3C 4D 5D 6H", "4S AH 3S 2D 5H"};
        size_t actual[100];
