        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"4H 4S 4D 9S 9D", "5H 5S 5D 8S 8D"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"5H 5S 5D 9S 9D", "5H 5S 5D 8S 8D"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"4S 5H 4D 5D 4H", "3S 3H 2S 3D 3C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2S 2H 2C 8D 2D", "4S 5H 5S 5D 5C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"3S 3H 2S 3D 3C", "3S 3H 4S 3D 3C"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"4S 5H 5S 5D 5C", "7S 8S 9S 6S 10S"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"KC AH AS AD AC", "10C JC QC KC AC"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"KS AH AS AD AC", "4H AH 3H 2H 5H"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2C AC QC 10C KC", "QH KH AH 2H 3H"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    {
        const char *values[] = {"4H 6H 7H 8H 5H", "5S 7S 8S 9S 6S"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        const char *values[] = {"2H 3H 4H 5H 6H", "4D AD 3D 2D 5D"};
        size_t actual[100];
        assert(best_hands(values, 2, actual) == 1);
        assert(actual[0] == 0);
    }
    return 0;
}
